<template>
  <div class="user-center-design" data-testid="user-center-design-page">
    <div class="heading"><div><h2>个人中心设计</h2><p>编辑六个模块、广告轮播与服务菜单，点击手机预览选择模块。</p></div><el-button data-testid="user-center-reread" :disabled="!canView || controller.locked" @click="controller.reread()">读取当前版本并保留草稿</el-button></div>
    <el-alert v-if="!canView" title="没有个人中心设计查看权限" type="warning" :closable="false" />
    <template v-else>
      <el-alert v-if="!canManage" title="当前仅有查看权限，个人中心设计不可修改" type="info" :closable="false" data-testid="user-center-view-only" />
      <el-alert v-if="state.error" :title="state.error" type="error" :closable="false" data-testid="user-center-read-error" />
      <el-alert v-if="state.notice" :title="state.notice" :type="state.success?'success':'warning'" :closable="false" data-testid="user-center-notice" />
      <el-alert v-if="state.recoveryError" :title="state.recoveryError" type="error" :closable="false" data-testid="user-center-recovery-error" />
      <el-alert v-if="state.pending" title="原请求结果尚未确认，已锁定编辑与新的提交" type="warning" :closable="false" show-icon data-testid="user-center-unknown"><p>本账号的原请求会在刷新后保留。请先核对回执；明确未找到回执后，可主动原样重试。</p><div class="actions"><el-button data-testid="user-center-receipt" :disabled="state.busy || state.readingReceipt || state.confirming || state.restoring" @click="controller.readReceipt()">读取原请求回执</el-button><el-button v-if="state.retryReady" data-testid="user-center-retry-original" :disabled="!canManage || state.busy || state.readingReceipt || state.confirming || state.restoring" @click="controller.retryOriginal()">原样重试</el-button></div></el-alert>
      <el-alert v-if="state.snapshot && !state.snapshot.configured && state.snapshot.editable" title="尚未保存个人中心设计，当前采用原商城默认模块与已有广告、菜单。读取不会创建记录。" type="info" :closable="false" data-testid="user-center-unconfigured" />
      <el-alert v-if="state.snapshot && !state.snapshot.editable" title="个人中心配置或共享广告、菜单异常，写入已暂停。默认预览示例不代表已保存配置。" type="error" :closable="false" data-testid="user-center-damaged" />
      <el-alert v-if="state.needsReread" title="本次未保存，草稿已保留。请读取当前版本并核对；无法对应原条目时，可采用当前配置重新编辑。" type="warning" :closable="false" data-testid="user-center-needs-reread"><el-button data-testid="user-center-adopt-current" :disabled="controller.locked" @click="controller.adoptCurrent()">采用当前配置重新编辑</el-button></el-alert>
      <ul v-if="state.snapshot?.issues.length" class="diagnostics" data-testid="user-center-diagnostics"><li v-for="(issue,index) in state.snapshot.issues" :key="index">{{ issueLabel(issue) }}</li></ul>
      <details v-if="state.rejected" data-testid="user-center-rejected-intent"><summary>核对上次未保存的六模块与全部列表</summary><pre>{{ JSON.stringify(state.rejected.input.value,null,2) }}</pre></details>
      <div class="workspace" v-loading="state.loading || state.restoring">
        <section class="preview-panel"><div class="panel-heading"><strong>实时预览</strong><span>示例账号</span></div><div class="preview-viewport" data-testid="user-center-preview-viewport"><UserCenterDesignPreview :value="state.draft" :active="active" :image="imagePreview" @select="selectModule" /></div><p>实际账号信息、订单与经营数据由商城读取，商家入口按当前账号权限展示。隐藏模块保留编辑入口。</p></section>
        <section class="editor" aria-label="个人中心模块设置">
          <nav class="module-picker" aria-label="选择编辑模块"><button v-for="module in modules" :key="module.key" type="button" :data-testid="`user-center-module-${module.key}`" :aria-pressed="active===module.key" :class="{chosen:active===module.key}" @click="selectModule(module.key)">{{ module.title }}</button></nav>
          <div class="editor-content" :data-testid="`user-center-editor-${active}`"><h3>{{ currentModule.title }}</h3>
            <template v-if="active==='member'">
              <div class="field" data-testid="user-center-control-member-style"><label>会员信息样式</label><el-radio-group :model-value="state.draft.member.style" :disabled="controller.editorDisabled" @change="memberStyle"><el-radio v-for="style in 5" :key="style" :value="style">样式 {{ style }}</el-radio></el-radio-group><p>样式一最多五项资产，其余最多三项。切换样式会采用余额、优惠券、积分三项，随后可重新选择。</p></div>
              <fieldset class="field" :disabled="controller.editorDisabled" data-testid="user-center-control-member-property"><legend>显示资产</legend><div class="selections"><el-checkbox v-for="option in propertyOptions" :key="option.id" :model-value="state.draft.member.property.includes(option.id)" :disabled="controller.editorDisabled || option.id===4 || !state.draft.member.property.includes(option.id) && state.draft.member.property.length>=propertyMaximum" @change="(checked:unknown)=>controller.toggleProperty(option.id,checked)">{{ option.label }}{{ option.id===4?'（历史项）':'' }}</el-checkbox></div><p v-if="state.draft.member.property.includes(4)" data-testid="user-center-historical-video">历史视频收藏完整保留。切换会员样式会按新的资产选择更新。</p><p v-if="!state.draft.member.property.length">当前未选择资产入口，可保存空选择。</p></fieldset>
              <div class="field" data-testid="user-center-control-member-per-show-type"><label>账号标识</label><el-radio-group :model-value="state.draft.member.per_show_type" :disabled="controller.editorDisabled" @change="(value:unknown)=>setToggle('member','per_show_type',value)"><el-radio :value="0">手机号</el-radio><el-radio :value="1">UID</el-radio></el-radio-group><p>头像和昵称使用实际会员资料。</p></div>
            </template>
            <template v-else-if="active==='order'"><div class="field" data-testid="user-center-control-order-style"><label>订单中心样式</label><el-radio-group :model-value="state.draft.order.style" :disabled="controller.editorDisabled" @change="(value:unknown)=>setStyle('order',value)"><el-radio v-for="style in 3" :key="style" :value="style">样式 {{ style }}</el-radio></el-radio-group><p>全部订单、待付款、待发货、待收货、待评价与售后入口读取实际订单。</p></div></template>
            <template v-else-if="active==='orderStatic'"><div class="field" data-testid="user-center-control-statistics-show"><label>是否显示</label><el-radio-group :model-value="state.draft.orderStatic.is_show" :disabled="controller.editorDisabled" @change="(value:unknown)=>setToggle('orderStatic','is_show',value)"><el-radio :value="1">显示</el-radio><el-radio :value="0">隐藏</el-radio></el-radio-group></div><div class="field" data-testid="user-center-control-statistics-style"><label>运营统计样式</label><el-radio-group :model-value="state.draft.orderStatic.style" :disabled="controller.editorDisabled" @change="(value:unknown)=>setStyle('orderStatic',value)"><el-radio :value="1">样式 1</el-radio><el-radio :value="2">样式 2</el-radio></el-radio-group><p>运营统计仅向拥有相应权限的当前账号展示。</p></div></template>
            <template v-else>
              <div class="field" :data-testid="`user-center-control-${active}-show`"><label>是否显示</label><el-radio-group :model-value="state.draft[listKey].is_show" :disabled="controller.editorDisabled" @change="(value:unknown)=>setToggle(listKey,'is_show',value)"><el-radio :value="1">显示</el-radio><el-radio :value="0">隐藏</el-radio></el-radio-group><p>隐藏后图片、链接和顺序仍会完整保存。</p></div>
              <template v-if="listKey!=='poster'"><div class="field" :data-testid="`user-center-control-${listKey}-title`"><label>模块标题</label><el-input :model-value="state.draft[listKey].title" :maxlength="100" :disabled="controller.editorDisabled" @update:model-value="(value:string)=>controller.edit(draft=>{if(listKey!=='poster')draft[listKey].title=value;})" /></div><div class="field" :data-testid="`user-center-control-${listKey}-style`"><label>菜单样式</label><el-radio-group :model-value="state.draft[listKey].style" :disabled="controller.editorDisabled" @change="(value:unknown)=>setStyle(listKey,value)"><el-radio v-for="style in 3" :key="style" :value="style">样式 {{ style }}</el-radio></el-radio-group></div></template>
              <p class="list-hint">{{ listKey==='merMenu'?'商家入口沿用当前已配置角色目标，仅支持名称、图片及排序。入口权限由商城判断。':`最多 ${listMaximum} 项，可选择素材和有效页面链接，支持调整顺序。` }}</p>
              <ol class="item-list" :data-testid="`user-center-list-${listKey}`"><li v-for="(item,index) in state.draft[listKey].list" :key="item.sourceId ?? `new-${index}`" :data-testid="`user-center-item-${listKey}-${index}`">
                <div class="item-heading"><strong>{{ index+1 }}. {{ item.name }}</strong><div class="actions"><el-button size="small" :disabled="controller.editorDisabled || index===0" :aria-label="`上移第${index+1}项`" @click="controller.move(listKey,index,-1)">上移</el-button><el-button size="small" :disabled="controller.editorDisabled || index===state.draft[listKey].list.length-1" :aria-label="`下移第${index+1}项`" @click="controller.move(listKey,index,1)">下移</el-button><el-button v-if="listKey!=='merMenu'" size="small" :disabled="controller.editorDisabled" :aria-label="`删除第${index+1}项`" @click="controller.remove(listKey as 'poster'|'menu',index)">删除</el-button></div></div>
                <label>名称</label><el-input :model-value="item.name" :maxlength="100" :disabled="controller.editorDisabled" :aria-label="`第${index+1}项名称`" @update:model-value="(value:string)=>editItem(index,'name',value)" />
                <div class="media-row"><img v-if="imagePreview(listKey,index,item.pic)" :src="imagePreview(listKey,index,item.pic)" :alt="item.name" /><span v-else class="missing-preview">素材预览待读取</span><div><el-button :disabled="controller.editorDisabled" :aria-label="`选择第${index+1}项图片`" @click="openPicker('asset',index)">选择图片</el-button><small>{{ item.pic }}</small></div></div>
                <div class="link-row"><label>链接</label><code>{{ item.url }}</code><el-button v-if="listKey!=='merMenu'" :disabled="controller.editorDisabled" :aria-label="`选择第${index+1}项链接`" @click="openPicker('link',index)">选择链接</el-button><span v-else class="hint">固定角色目标</span></div>
              </li></ol>
              <p v-if="!state.draft[listKey].list.length" class="empty">当前列表为空。</p>
              <fieldset v-if="listKey!=='merMenu'" class="add-item" :disabled="controller.editorDisabled || state.draft[listKey].list.length>=listMaximum" :data-testid="`user-center-add-${listKey}`"><legend>添加{{ listKey==='poster'?'广告':'服务菜单' }}</legend><el-input v-model="newItem.name" :disabled="controller.editorDisabled || state.draft[listKey].list.length>=listMaximum" :maxlength="100" placeholder="填写名称" aria-label="新增项目名称" /><div class="actions"><el-button :disabled="controller.editorDisabled || state.draft[listKey].list.length>=listMaximum" @click="openPicker('asset',null)">选择图片</el-button><el-button :disabled="controller.editorDisabled || state.draft[listKey].list.length>=listMaximum" @click="openPicker('link',null)">选择链接</el-button><el-button type="primary" :disabled="controller.editorDisabled || state.draft[listKey].list.length>=listMaximum || !newItem.name.trim() || !newItem.pic || !newItem.url" @click="addItem">添加到列表</el-button></div><img v-if="selectedPreviews[newItem.pic]" :src="selectedPreviews[newItem.pic]" alt="新增素材" class="new-image" /><small v-if="newItem.pic">{{ newItem.pic }}</small><code v-if="newItem.url">{{ newItem.url }}</code></fieldset>
            </template>
          </div>
          <div class="editor-actions"><span data-testid="user-center-dirty">{{ controller.dirty?'草稿有未保存修改':'当前草稿尚未修改' }}</span><el-button v-if="canManage" type="primary" data-testid="user-center-save" :disabled="controller.editorDisabled || state.needsReread" :loading="state.busy" @click="controller.save()">保存个人中心设计</el-button></div>
        </section>
      </div>
      <UserCenterDesignPicker :open="pickerOpen" :mode="pickerMode" :identity="identity" :can-edit="!controller.editorDisabled" @close="pickerOpen=false" @choose="choose" />
    </template>
  </div>
</template>
<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,reactive,ref,watch } from 'vue';
import { ElMessageBox } from 'element-plus';
import { useAuthStore } from '@/stores/auth';
import { getAdminSession,getToken } from '@/utils/auth';
import { apiUserCenterDesign,apiSaveUserCenterDesign,apiUserCenterDesignReceipt } from '@/api/userCenterDesign';
import { userCenterDesignIssueLabel as issueLabel } from '@/utils/userCenterDesignDiagnostics';
import { USER_CENTER_DESIGN_MODULES,USER_CENTER_PROPERTY_OPTIONS, type UserCenterDesignValue } from '../../../../common/userCenterDesign';
import { UserCenterDesignController } from '../../../../common/userCenterDesignController';
import UserCenterDesignPreview from './UserCenterDesignPreview.vue';
import UserCenterDesignPicker from './UserCenterDesignPicker.vue';
type ModuleKey=keyof UserCenterDesignValue;type ListKey='poster'|'menu'|'merMenu';
const modules=USER_CENTER_DESIGN_MODULES,propertyOptions=USER_CENTER_PROPERTY_OPTIONS,active=ref<ModuleKey>('member'),currentModule=computed(()=>modules.find(row=>row.key===active.value)??modules[0]);
const listKey=computed<ListKey>(()=>['poster','menu','merMenu'].includes(active.value)?active.value as ListKey:'poster');
const auth=useAuthStore(),canView=computed(()=>!!auth.token&&auth.token===getToken()&&!!auth.userInfo&&(auth.userInfo.level===0||auth.uniqueAuth.includes('user_center_design.view'))),canManage=computed(()=>canView.value&&!!auth.userInfo&&(auth.userInfo.level===0||auth.uniqueAuth.includes('user_center_design.manage'))),identity=computed(()=>`${auth.token}:${auth.userInfo?.id}:${auth.userInfo?.level}:${auth.uniqueAuth.join(',')}`);
const controller=new UserCenterDesignController(()=>({id:auth.userInfo?.id??null,identity:identity.value,stored:localStorage.getItem('admin_session'),view:canView.value,manage:canManage.value}),{read:apiUserCenterDesign,write:apiSaveUserCenterDesign,receipt:apiUserCenterDesignReceipt,storage:sessionStorage,uuid:()=>crypto.randomUUID(),confirm:async message=>{await ElMessageBox.confirm(message,'确认个人中心设计',{type:'warning',confirmButtonText:'确认',cancelButtonText:'取消',customClass:'user-center-design-confirm'});}},value=>reactive(value));
const state=controller.state,propertyMaximum=computed(()=>state.draft.member.style===1?5:3),listMaximum=computed(()=>listKey.value==='poster'?10:30);
const newItem=reactive({name:'',pic:'',url:''}),selectedPreviews=reactive<Record<string,string>>({}),pickerOpen=ref(false),pickerMode=ref<'asset'|'link'>('asset');
let target:{key:ListKey;index:number|null;signature:string;identity:string}|null=null;
function clearNew(){Object.assign(newItem,{name:'',pic:'',url:''});}
function selectModule(key:string){if(modules.some(row=>row.key===key)){active.value=key as ModuleKey;pickerOpen.value=false;target=null;clearNew();}}
function memberStyle(value:unknown){if(typeof value==='number'&&Number.isSafeInteger(value)&&value>=1&&value<=5&&value!==state.draft.member.style)controller.edit(draft=>{draft.member.style=value as UserCenterDesignValue['member']['style'];draft.member.property=[0,1,2];});}
function setToggle(key:ModuleKey,field:'is_show'|'per_show_type',value:unknown){if(value!==0&&value!==1)return;controller.edit(draft=>{if(key==='member'&&field==='per_show_type')draft.member.per_show_type=value;else if(field==='is_show'&&['orderStatic','poster','menu','merMenu'].includes(key))(draft[key] as {is_show:0|1}).is_show=value;});}
function setStyle(key:ModuleKey,value:unknown){if(typeof value!=='number'||!Number.isSafeInteger(value)||key==='member'||key==='poster')return;controller.edit(draft=>{(draft[key] as {style:number}).style=value;});}
function editItem(index:number,field:'name'|'pic'|'url',value:string){const key=listKey.value;controller.edit(draft=>{const item=draft[key].list[index];if(item&&(key!=='merMenu'||field!=='url'))item[field]=value;});}
function imagePreview(key:ListKey,index:number,pic:string){if(selectedPreviews[pic])return selectedPreviews[pic];const item=state.draft[key].list[index],snapshot=state.snapshot;if(!item||!snapshot?.value)return '';const source=snapshot.value[key].list.findIndex(row=>row.sourceId===item.sourceId&&row.pic===pic);return source>=0?snapshot.imagePreviews[key][source]??'':'';}
function openPicker(mode:'asset'|'link',index:number|null){if(controller.editorDisabled||mode==='link'&&listKey.value==='merMenu'||index===null&&listKey.value==='merMenu')return;const item=index===null?newItem:state.draft[listKey.value].list[index];if(!item)return;target={key:listKey.value,index,signature:JSON.stringify(item),identity:identity.value};pickerMode.value=mode;pickerOpen.value=true;}
function choose(value:string,preview?:string){if(controller.editorDisabled||!target||target.identity!==identity.value||target.key!==listKey.value)return;const item=target.index===null?newItem:state.draft[target.key].list[target.index];if(!item||JSON.stringify(item)!==target.signature){state.notice='原条目已变化，请重新选择。';return;}if(pickerMode.value==='asset'&&preview)selectedPreviews[value]=preview;const field=pickerMode.value==='asset'?'pic':'url';if(target.index===null)newItem[field]=value;else editItem(target.index,field,value);target=null;}
function addItem(){const key=listKey.value;if(key==='merMenu'||!newItem.name.trim()||!newItem.pic||!newItem.url)return;const item={sourceId:null,name:newItem.name.trim(),pic:newItem.pic,url:newItem.url};if(controller.edit(draft=>{if(key==='poster')draft.poster.list.push(item);else draft.menu.list.push({...item,type:1});}))clearNew();}
let alive=false,syncing=false;
function clearLocal(){pickerOpen.value=false;target=null;clearNew();Object.keys(selectedPreviews).forEach(key=>delete selectedPreviews[key]);active.value='member';}
function syncStored(event?:Event){if(syncing||event instanceof StorageEvent&&event.key!==null&&!['admin_token','admin_session'].includes(event.key))return;syncing=true;if(state.confirming)ElMessageBox.close();controller.invalidate();clearLocal();const session=getAdminSession();auth.$patch({token:getToken()??'',userInfo:session?.userInfo??null,menus:(session?.menus as typeof auth.menus)??[],uniqueAuth:session?.uniqueAuth??[]});syncing=false;void controller.activate();}
watch(identity,()=>{if(alive&&!syncing){if(state.confirming)ElMessageBox.close();clearLocal();void controller.activate();}},{flush:'sync'});
watch(()=>controller.editorDisabled,disabled=>{if(disabled){pickerOpen.value=false;target=null;}},{flush:'sync'});
onMounted(()=>{alive=true;window.addEventListener('storage',syncStored);window.addEventListener('admin-session-changed',syncStored);window.addEventListener('admin-auth-expired',syncStored);syncStored();});
onBeforeUnmount(()=>{alive=false;if(state.confirming)ElMessageBox.close();controller.dispose();clearLocal();window.removeEventListener('storage',syncStored);window.removeEventListener('admin-session-changed',syncStored);window.removeEventListener('admin-auth-expired',syncStored);});
</script>
